      if (!frontDoor(17, 25, 23, GND, '#6a4a30', { hinge: 'LR', edge: '#3a2418' })) ln(20, 22.5, 20, GND, '#3a2418', 0.35);
      porchLamp(15.5, 25); porchLamp(24.5, 25);
