      hatch(FP([[21, 20], [29, 14.5], [37, 20]]), metal, 1.1, true, 'rgba(255,255,255,0.10)');
      ln(F(21), 20, F(29), 14.5, frameC, 0.6); ln(F(29), 14.5, F(37), 20, frameC, 0.6);
      win(FR(24, 5), 22, 5, 5.5, 3, frameC, true);
