    if (detail) for (let k = 0; k < 30; k++) dot(122 + _cmFrac(k * 3.1) * 180, 46 + _cmFrac(k * 7.3) * 8, 1.2, L('#8aba5a', '#2e4a2a', '#1a2414'));
