    // ── Stepped parapet with a chevron frieze ──
    R(42, 12, 36, 8, CREAM); R(30, 19, 60, 8, CREAM);
    R(42, 12, 36, 1.4, TRIM); R(30, 19, 60, 1.4, TRIM);
    R(8, 26, 104, 4, CREAM); R(8, 26, 104, 1.4, TRIM);
    if (detail) for (let x = 10; x < 110; x += 5) poly([[x, 30], [x + 2.5, 27.6], [x + 5, 30]], CORAL);

    // ── Body, with a rounded left corner ──
