    const cg = ctx.createLinearGradient(X(8), 0, X(24), 0);
    cg.addColorStop(0, 'rgba(0,0,0,0.22)'); cg.addColorStop(0.5, 'rgba(255,255,255,0.08)'); cg.addColorStop(1, 'rgba(0,0,0,0)');
