      R(cx + 10.5, GND - 0.8, 4, 1.4, '#f4f0e0');
      circ(cx + 5, GND + 9.2, 1.9, '#1a1a1c'); circ(cx + 19, GND + 9.2, 1.9, '#1a1a1c');
      circ(cx + 23.6, GND + 6, 0.8, '#fff6c8'); glow(cx + 25, GND + 6, 6, '255,240,180', 0.4);
