    // crown fin + aviation light
    R(18, 4, 8, 34, on || !dim ? '#f0f0ec' : '#6a6a68');
    if (detail) {
      R(24, 6, 2, 32, 'rgba(0,0,0,0.12)');                                  // shaded side of the fin
      if (fine) for (let y = 10; y < 32; y += 5) ln(18, y, 24, y, 'rgba(0,0,0,0.1)', 0.4);   // panel joints
    }
    const blink = on && Math.sin(t*2.4) > 0.3;
    circ(22, 4, 1.4, blink ? '#ff3020' : '#5a1a14');
    if (blink && dim) { ctx.fillStyle = 'rgba(255,60,40,0.25)'; ctx.beginPath(); ctx.arc(K.X(22), K.Y(4), 6*K.sm, 0, Math.PI*2); ctx.fill(); }
    // roof deck + infinity pool + cabanas
    R(14, 32, 92, 4, on || !dim ? '#d8d6d0' : '#5a5a58');
    R(46, 26, 56, 6, on || !dim ? '#c8c4bc' : '#4a4a48');
    R(48, 27, 52, 4, on ? (dim ? '#2a8ab8' : '#4ac0e8') : '#2a4450');
    if (on && detail) for (let k = 0; k < 5; k++) R(50 + ((t*4 + k*11) % 48), 28 + (k % 2), 3, 0.6, 'rgba(255,255,255,0.6)');
    if (on && detail) R(100, 27, 2, 5, dim ? 'rgba(120,210,255,0.45)' : 'rgba(220,245,255,0.6)');   // water slipping over the infinity edge
