    if (fine) for (let y = 56; y < GND - 26; y += 6) ln(8, y, 112, y, 'rgba(120,100,70,0.12)', 0.4);
    R(8, GND - 26, 104, 26, STONE_D);                                              // rusticated base
    if (detail) for (let y = GND - 22; y < GND; y += 4) ln(8, y, 112, y, 'rgba(80,60,40,0.3)', 0.6);
    R(110, 50, 2, GND - 50, 'rgba(0,0,0,0.12)');
    // central bay column
