    if (on && K.hr >= 7 && K.hr < 23) { R(86, GND - 7, 2.6, 6, '#2a3a2e'); circ(87.3, GND - 8.4, 1.3, '#e0c0a0'); R(85.9, GND - 10, 2.8, 1, '#2a3a2e'); }
