      R(0.725, 0.412, 0.09, 0.07, S('rgba(140,160,150,0.30)', 'rgba(90,100,110,0.22)', 'rgba(40,40,40,0.2)'));
      if (fine) {
        R(0.742, 0.30, 0.004, 0.18, S('#5a5650', '#3a3c44', '#1a1a1a'));
        R(0.794, 0.30, 0.004, 0.18, S('#5a5650', '#3a3c44', '#1a1a1a'));
      }

      // ── Clubhouse: two storeys, balcony, striped awning ─────────────
      R(0.05, 0.175, 0.31, 0.13, wallC);
      R(0.08, 0.085, 0.25, 0.092, wallC);
      if (fine) {                                   // weatherboards
        ctx.fillStyle = 'rgba(0,0,0,0.07)';
        for (let k = 0; k < 6; k++) ctx.fillRect(X(0.05), Y(0.19 + k*0.02), W*0.31, H*0.003);
        for (let k = 0; k < 4; k++) ctx.fillRect(X(0.08), Y(0.095 + k*0.02), W*0.25, H*0.003);
      }
      R(0.31, 0.085, 0.02, 0.092, wallD);           // shaded return
      R(0.34, 0.175, 0.02, 0.13, wallD);
      poly([[0.055, 0.092], [0.12, 0.030], [0.29, 0.030], [0.355, 0.092]], navy);
      R(0.12, 0.030, 0.17, 0.006, S('#4a7cab', '#2c4870', '#1a2230'));   // ridge
      // Name board on the roof
      R(0.095, 0.050, 0.22, 0.032, S('#f4f1e8', '#b8bccb', '#34332e'));
      label('BOAT CLUB', X(0.205), Y(0.074), 2.2, S('#2d5f8c', '#2a3a58', 'rgba(20,24,30,0.8)'));
      // Upper windows
      for (let k = 0; k < 4; k++) {
        const lit = on && night && (open || k === 1);
        R(0.10 + k*0.056, 0.105, 0.036, 0.048, lit ? warm(0.6 + 0.12*Math.sin(t*1.3 + k)) : glassC);
        if (fine) R(0.117 + k*0.056, 0.105, 0.003, 0.048, wallD);
      }
      // Balcony slab and railing
      R(0.04, 0.170, 0.33, 0.012, navy);
      R(0.04, 0.150, 0.33, 0.004, wallC);
      if (fine) for (let k = 0; k <= 11; k++) R(0.042 + k*0.029, 0.150, 0.003, 0.020, wallC);
      // Striped awning over the ground floor
      for (let k = 0; k < 11; k++) R(0.05 + k*0.0282, 0.182, 0.0282, 0.018, k % 2 ? wallC : navy);
      // Ground-floor glazing, doors in the middle
