  ctx.strokeStyle = L('#e8c860', '#9a8448', '#3a3428'); ctx.lineWidth = 0.5 * S; ctx.beginPath(); ctx.roundRect(X(6.8), Y(SF + 1.4), 66.4 * S, 5.4 * S, 0.8 * S); ctx.stroke();
  text('DOWNTOWN CAFÉ', 42, SF + 4.2, 4, open ? '#fff4dc' : L('#f0e6d0', '#b8ae98', '#3a3832'), 'Georgia, serif');
  // cup icon with a curl of steam
