      ctx.save(); ctx.translate(cx, cy); ctx.scale(1, 0.6); _cmCar(0, 0, '#3060c0', S, false); ctx.restore();
      if (dark > 0.35) { ctx.fillStyle = 'rgba(255,246,200,0.35)'; ctx.beginPath(); ctx.moveTo(cx + 8*S, cy); ctx.lineTo(cx + 22*S, cy - 3*S); ctx.lineTo(cx + 22*S, cy + 3*S); ctx.closePath(); ctx.fill(); }
