  const cleaning = on && hr >= 23, early = on && hr >= 4 && hr < 5;
  const detail = Camera.zoom > 0.45;
  const L = (d, n, o) => on ? (night ? n : d) : o;
  const busy = k => open && (rush || _cmFrac((e.col || 0) + k*7) < 0.62);
  const ORANGE = '#ff6a2a', FRAME = L('#3a3e48', '#2a2e36', '#18191c');
  // A figure seen side-on, hips at (x, hy): each foot is an offset from the
