    if (!open && on) for (const sx of [-1.6, 1.6]) poly([[tx + sx - 1, ty - 3.6], [tx + sx + 1, ty - 3.6], [tx + sx + 0.7, ty - 7.2], [tx + sx - 0.7, ty - 7.2]], L('#4a3422', '#2e2216', '#1e160e'));   // chairs up
