  R(8, 1, 16, 7, L('#9aa2a6', '#4a5056', '#2a2c30')); R(8, 1, 16, 0.9, L('#c4cad0', '#5e646c', '#34363a'));
  ctx.save(); ctx.translate(K.X(13), K.Y(4.6));
  ctx.fillStyle = L('#3a3e44', '#22262c', '#1a1b1e'); ctx.beginPath(); ctx.arc(0, 0, 2.6*K.S, 0, Math.PI*2); ctx.fill();
  ctx.rotate(on ? t*9 : 0.4); ctx.fillStyle = L('#7a8288', '#444a50', '#2a2c2e');
  for (let b = 0; b < 3; b++) { ctx.rotate(Math.PI*2/3); ctx.fillRect(-0.45*K.S, 0, 0.9*K.S, 2.3*K.S); }
  ctx.restore();
  for (let g = 0; g < 4; g++) R(17 + g*1.6, 2.6, 0.8, 4.4, L('#6a7278', '#33383c', '#202224'));

  // ── Upstairs: white render, consulting-room windows ──
  R(3, 7, 74, 25, L('#f2f2ee', '#6a6c70', '#2a2a2c'));
