  text('24H', dX + 7, 40.4, 1.9, nightSvc ? '#ffffff' : day ? 'rgba(220,240,234,0.8)' : 'rgba(80,100,94,0.6)', 'Arial, sans-serif');
  if (nightSvc) glow(dX + 7, 40.4, 8, '60,230,180', 0.35);

