  RR(19.5, 39.2, 47, 4.4, 0.8, L('#ffd24a', '#a87818', '#4a3c14'));
  R(19.5, 39.2, 47, 0.9, L('#fff0a0', '#c89828', '#5a4a18'));

  // top bun
  {
    const g = ctx.createRadialGradient(K.X(34), K.Y(26), 2 * K.S, K.X(42), K.Y(32), 22 * K.S);
    g.addColorStop(0, L('#ffe7a4', '#8a6030', '#4a3c28'));
    g.addColorStop(0.55, L('#f0b040', '#6a4014', '#3a2814'));
    g.addColorStop(1, L('#d48420', '#3a200c', '#241810'));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(K.X(42), K.Y(29.5), 19 * K.S, 12.2 * K.S, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = L('#a86418', '#3a2010', '#1e1810');
    ctx.lineWidth = 0.7 * K.S;
    ctx.stroke();
  }
  if (on && !night) ell(33, 25.5, 7, 3.2, 'rgba(255,240,190,0.55)');
  const seeds = [[27, 27], [31, 32], [37, 34.5], [46, 34], [53, 29], [25, 32], [49, 25.5], [34, 27], [52, 34], [40, 31]];
  for (const [sx, sy] of seeds) {
    ell(sx + 0.3, sy + 0.35, 1.15, 0.65, 'rgba(80,50,16,0.28)');
    ell(sx, sy, 1.15, 0.65, L('#fff4d4', '#8a7050', '#4a4030'));
  }

  // lettuce fringe
  for (let i = 0; i < 10; i++) {
    const lx = 18 + i * 5.3;
    ell(lx, 40.2, 3.5, 2.5, i % 2
      ? L('#92dc4e', '#3a6020', '#1c3014')
      : L('#6ec238', '#2a4a18', '#142410'));
  }
  // cheese drip
  poly([[61.5, 41.2], [67.2, 41.6], [64.2, 50.5], [60.2, 44.2]], L('#ffd24a', '#a87818', '#4a3c14'));
  poly([[62.2, 41.4], [65.5, 41.6], [64, 44], [61.8, 42.6]], L('#fff0a0', '#c89828', '#5a4a18'));

