  poly([[40.4, 14.8], [38.6, 17.8], [39.9, 17.8], [39.2, 20.6], [42.8, 16.8], [41.2, 16.8], [42.2, 14.8]],
    L('#ffd24a', '#ffe080', '#4a3c14'));

