  R(68.4, 58.2, 5.2, 2.2, on ? (night ? '#3a90ff' : '#1a4a8a') : '#101418');       // order-total screen
  if (detail) for (let k = 0; k < 3; k++) R(68.6 + k * 1.8, 61.1, 1.1, 0.6, L('#5a6268', '#2a3036', '#1a1c20'));   // grille

