    const arrowW = (x, y) => poly([[x, y], [x + 3, y - 2], [x + 3, y - 0.8], [x + 6.5, y - 0.8], [x + 6.5, y + 0.8], [x + 3, y + 0.8], [x + 3, y + 2]], paint);
    arrowW(58.5, 71); arrowW(76, 71);
