    ctx.fillStyle = 'rgba(0,0,0,0.3)'; ctx.beginPath(); ctx.ellipse(0.4, 0.6, 4, 1.6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#d8402a'; ctx.beginPath(); ctx.roundRect(-3.2, -1.1, 6.4, 2.2, 0.9); ctx.fill();
