    if (moving && on && night) { ctx.fillStyle = 'rgba(255,240,200,0.5)'; ctx.beginPath(); ctx.moveTo(3, -0.6); ctx.lineTo(10, -2.4); ctx.lineTo(10, 2.4); ctx.lineTo(3, 0.6); ctx.fill(); }
