  for (let k = 0; k < 14; k++) { const a = k / 14 * Math.PI * 2, r = 22 + hash(k + 400) * 6; dot(TX + Math.cos(a) * r, TY + Math.sin(a) * r, 9 + hash(k + 420) * 4, ROCK[k % 3]); }
  dot(TX, TY, 24, ROCK[1]); dot(TX - 2, TY - 2, 17, ROCK[0]);
  for (let k = 0; k < 9; k++) { const a = k * 2.4, r = 20 + hash(k + 440) * 9; dot(TX + Math.cos(a) * r, TY + Math.sin(a) * r, 2.6 + hash(k + 450) * 1.6, L(k % 2 ? '#3a8a3a' : '#2e7a30', '#16301c', '#121a12')); }   // scrub on the flanks
