      dot(bx, by, 14, L('#40b060', '#1e5a30', '#1a2a1e')); dot(bx, by, 10, L('#5ad080', '#2a7a40', '#1e3424'));
      dot(bx, by, 4, L('#2a7a40', '#123a20', '#101a12'));
