    if (on) for (let k = 0; k < 5; k++) { const q = (t * 1.1 + k / 5 + hx) % 1; dot(hx + Math.cos(k * 2.3) * 4 * q, hy + Math.sin(k * 2.3) * 4 * q, 0.8 + q, `rgba(255,255,255,${(0.7 * (1 - q)).toFixed(2)})`); }
    if (open && detail) for (let k = 0; k < 3; k++) dot(hx + Math.cos(k * 2.1 + hy) * 4.6, hy + Math.sin(k * 2.1 + hy) * 4.6, 1.2, _N_SKIN[(k + hx) % 6 | 0]);
    if (on && night) glow(hx, hy, 14, '90,220,255', 0.3);
