  if (open && detail) for (let k = 0; k < 6; k++) { const a = k / 6 * Math.PI * 2; dot(216 + Math.cos(a) * 14.5, 177 + Math.sin(a) * 14.5, 1.2, _N_SKIN[k % 6]); }
