      if (gap <= 1.5) { const q = (t * 0.6) % 1; dot(fx(0.38) - 0.6, fy(0.35) - q * 4, 0.7, '#ff2a5a'); dot(fx(0.38) + 0.6, fy(0.35) - q * 4, 0.7, '#ff2a5a'); poly([[fx(0.38) - 1.3, fy(0.36) - q * 4], [fx(0.38) + 1.3, fy(0.36) - q * 4], [fx(0.38), fy(0.36) - q * 4 + 1.6]], '#ff2a5a'); }
