      const rx = fx(0.15) + ((t * 2) % (w * 0.7)), step = Math.sin(t * 6);
      R(rx - 2, fy(0.3), 4, h * 0.32, '#8a9098'); R(rx - 1.2, fy(0.18), 2.4, 1.8, '#8a9098'); dot(rx + 0.5, fy(0.22), 0.4, '#ff2020');
