    if (detail) { ctx.strokeStyle = 'rgba(255,255,255,0.04)'; ctx.lineWidth = 0.5*S; for (let k = 1; k < 12; k++) { ctx.beginPath(); ctx.moveTo(X(hx + 6 + k*10), Y(hy + 6)); ctx.lineTo(X(hx + 6 + k*10), Y(hy + hh - 6)); ctx.stroke(); } }
    const cx = hx + 58, cy = hy + 62, rx = 40, ry = 36;
