    poly([[ux - 3, 86], [ux + 3, 86], [ux + 2, 90.6], [ux - 2, 90.6]], L('#1a1418', '#0e0a0e', '#060506'));
    R(ux - 3.4, 85.4, 6.8, 1, GOLD);
