    R(lx - 1.6, 97, 3.2, 2, L('#2a2a30', '#18181c', '#0c0c0e'));
    R(lx - 0.6, 72, 1.2, 25, L('#2a2a30', '#18181c', '#0c0c0e'));
    R(lx - 1.4, 73.4, 2.8, 0.8, GOLD);
