      // pulls back out — clear of the two parked at the kerb
      const u = (t * 0.035) % 1;
      let cx, oy;
      if (u < 0.3)       { cx = -20 + u / 0.3 * 110; oy = 8; }
      else if (u < 0.38) { cx = 90 + (u - 0.3) / 0.08 * 10; oy = 8 - (u - 0.3) / 0.08 * 8; }
      else if (u < 0.66) { cx = 100; oy = 0; }
      else if (u < 0.74) { cx = 100 + (u - 0.66) / 0.08 * 10; oy = (u - 0.66) / 0.08 * 8; }
