  if (detail) for (let x = 14; x < 110; x += 9) R(x, 6, 0.5, 14, 'rgba(0,0,0,0.14)');
  R(16, 7, 12, 8, L('#6a4238', '#2e1e1e', '#181010'));
  for (const cx of [19, 25]) dot(cx, 11, 1.8, L('#3a2420', '#181010', '#0c0808'));
  if (on && detail) for (let q = 0; q < 3; q++) { const ph = (t * 0.2 + q / 3) % 1; ell(19 + ph * 5, 9 - ph * 8, 1.5 + ph * 3, 1 + ph * 2, `rgba(200,200,210,${(0.25 * (1 - ph)).toFixed(3)})`); }
  R(48, 7, 24, 10, L('#2a2a30', '#141418', '#0c0c0e'));                                  // lantern light over the stage
  R(49.5, 8.5, 21, 7, open ? `rgba(255,${Math.round(175 + 30 * swing)},80,0.95)` : L('#6f8ea6', '#141a24', '#0c0e12'));
  if (detail) for (let x = 54.75; x < 70; x += 5.25) R(x, 8.5, 0.5, 7, '#1a1a20');
  if (open) glow(60, 12, 16, '255,180,90', 0.22);
  if (detail && !night) for (const [bx, by] of [[90, 9], [94, 11.5], [99, 8.5]]) { ell(bx, by, 1.3, 0.8, '#8a8e96'); dot(bx + 1, by - 0.5, 0.5, '#6a6e76'); }   // pigeons
