  if (detail) for (let k = 0; k < 26; k++) R(9 + hash(k) * 100, 24 + Math.floor(hash(k + 50) * 12) * 2.5, 3 + hash(k + 90) * 3, 2.5, hash(k + 130) > 0.5 ? 'rgba(160,170,255,0.07)' : 'rgba(0,0,0,0.14)');
