  vgrad(37.5, 30, 45, 25.5, open ? '#ffb850' : L('#4a5a70', '#141a26', '#0c0e12'), open ? '#c8501e' : L('#2a3444', '#0c1018', '#08090c'));
  if (open) poly([[52, 30], [70, 30], [79, 56], [43, 56]], 'rgba(255,240,190,0.24)');     // the spot
