  for (let i = 0; i < 8; i++) R(10 + i * 36, 187, 16, 1.5, L('rgba(255,255,255,0.4)', 'rgba(220,220,200,0.18)', 'rgba(0,0,0,0.1)'));
  if (open) glow(140, 164, 150, `255,${Math.round(40 + 60 * beat)},130`, 0.16 + beat * 0.14);

