  if (detail) for (let x = 10; x < 270; x += 13) R(x, 65.4, 0.5, 92.6, 'rgba(255,255,255,0.04)');
  R(10, 150, 260, 8, L('#101116', '#08090c', '#050506'));
  // LED fins on the wings: meters filling to the music
  for (let i = 0; i < 10; i++) {
    const fx = i < 5 ? 15 + i * 8.6 : 229 + (i - 5) * 8.6;
    R(fx, 70, 3.2, 78, L('#2a2c34', '#131419', '#0b0b0e'));
    if (on) {
      const lvl = open ? 0.2 + 0.8 * Math.abs(Math.sin(t * (1.6 + (i % 5) * 0.31) + i * 1.3)) * (0.55 + beat * 0.45) : (night ? 0.08 + 0.04 * Math.sin(t * 0.6 + i) : 0);
      const hgt = 78 * lvl;
      if (hgt > 0.5) { const g = ctx.createLinearGradient(0, Y(148), 0, Y(148 - hgt)); g.addColorStop(0, hsl(hue + 300, 55)); g.addColorStop(1, hsl(hue + 300 + lvl * 120, 62)); ctx.fillStyle = g; ctx.fillRect(X(fx + 0.4), Y(148 - hgt), 2.4 * S, hgt * S); }
      if (open) R(fx + 0.4, 148 - hgt - 1.6, 2.4, 0.9, '#ffffff');
    }
  }
  if (open) { glow(34, 120, 46, '200,80,255', 0.12 + beat * 0.08); glow(246, 120, 46, '200,80,255', 0.12 + beat * 0.08); }
