    for (let i = 0; i < 3; i++) { R(46 + i * 8, 166 - (i === 1 ? 2.6 : 0), 6, 4.4, '#1a1a1e'); R(46 + i * 8, 166 - (i === 1 ? 2.6 : 0), 6, 0.6, '#c8c8cc'); }      // flight cases
    person(72 + Math.sin(t * 0.6) * 6, 168, '#18181c', _CLUB_SKINS[1]);
