    if (detail) { ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 0.35 * S; ctx.beginPath(); ctx.arc(X(ax + 6), Y(ay + 5.4), 2.2 * S, 0, Math.PI * 2); ctx.stroke(); }
