  R(116, 121, 42, 3, BLUE);                                                          // canopy
  R(120, 124.5, 34, 5, '#0a0e12');                                                   // the ticker everyone works under
  if (on && detail) text(`CALLS WAITING ${Math.round((1.2 - shiftFill) * 14 + 6 * (0.5 + 0.5 * Math.sin(t * 0.25)))}`, 137, 127.1, 3, '#ffb040', 'Courier New');
  if (on && night) glow(137, GY, 30, '255,224,170', 0.25);
