  ln(196, 45, 196, 39, STEEL, 0.8);
  dot(196, 35, 5, L('#d8dce0', '#5a5e64', '#2a2c30')); dot(196, 35, 3.6, L('#eef0f2', '#6a6e74', '#34363a')); dot(197.5, 33.5, 0.8, '#3a3e44');
  ln(216, 45, 216, 14, STEEL, 0.8); ln(212, 24, 220, 24, STEEL, 0.6); ln(213, 31, 219, 31, STEEL, 0.6);
