  poly([[TC - 5, GY - 14], [TC - 3.4, 40], [TC + 3.4, 40], [TC + 5, GY - 14]], CONC);
  poly([[TC + 0.6, GY - 14], [TC + 0.4, 40], [TC + 3.4, 40], [TC + 5, GY - 14]], CONC_D);
  if (detail) for (let y = 48; y < GY - 14; y += 8) { const hw = 3.4 + 1.6 * (y - 40) / (GY - 54); R(TC - hw, y, hw * 2, 0.4, 'rgba(0,0,0,0.12)'); }   // formwork joints
