    const g = ctx.createRadialGradient(X(cx - 8), Y(cy - 9), 2 * S, X(cx), Y(cy), 24 * S);
    g.addColorStop(0, L('#ffffff', '#9aa2b0', '#3a3e44')); g.addColorStop(0.6, L('#e2e8ee', '#5a6270', '#2a2e32')); g.addColorStop(1, L('#9aa4ae', '#30363e', '#1a1c20'));
