    // frost on the underside
    ctx.save(); ctx.beginPath(); ctx.arc(X(cx), Y(cy), 22 * S, 0.15, Math.PI - 0.15); ctx.closePath(); ctx.clip();
    ctx.fillStyle = on ? 'rgba(240,250,255,0.45)' : 'rgba(120,130,140,0.25)'; ctx.fillRect(X(cx - 22), Y(cy + 4), 44 * S, 20 * S);
    if (detail) for (let j = 0; j < 10; j++) dot(cx - 16 + _cmFrac(cx + j) * 32, cy + 8 + _cmFrac(j * 3 + cx) * 12, 0.7, 'rgba(255,255,255,0.85)');
    ctx.restore();
