  R(HX, HY, HW, HB - HY, L('#dfe3e6', '#3e4450', '#22252a'));
  // sawtooth roof with north-light glazing
  for (let k = 0; k < 6; k++) {
    const rx = HX + k * HW / 6, rw = HW / 6;
    poly([[rx, HY], [rx + rw * 0.75, HY - 12], [rx + rw, HY - 12], [rx + rw, HY]], L('#b8bec6', '#2e343c', '#1a1c20'));
    poly([[rx + rw * 0.75, HY - 12], [rx + rw, HY - 12], [rx + rw, HY]], on ? (night ? 'rgba(255,230,170,0.85)' : 'rgba(170,215,240,0.9)') : '#1a2024');
  }
  // cutaway into the hall
