  ctx.strokeStyle = on ? 'rgba(255,210,150,0.55)' : 'rgba(80,60,40,0.4)'; ctx.lineWidth = 0.6 * S;
  for (const p of [-2.5, 0, 2.5]) { D(p); ctx.stroke(); }                                  // conductor turns
  // winding head travelling round the D, fed from the spool
  const dpt = s2 => {
    if (s2 < 0.35) return [DX - 22, DY + 40 - (s2 / 0.35) * 80];
    const u = (s2 - 0.35) / 0.65, x0 = DX - 22, y0 = DY - 40, c1x = DX + 48, c1y = DY - 44, c2x = DX + 48, c2y = DY + 44, x3 = DX - 22, y3 = DY + 40;
    const mt = 1 - u;
    return [mt * mt * mt * x0 + 3 * mt * mt * u * c1x + 3 * mt * u * u * c2x + u * u * u * x3, mt * mt * mt * y0 + 3 * mt * mt * u * c1y + 3 * mt * u * u * c2y + u * u * u * y3];
  };
  const [hx, hy] = dpt(on ? (t * 0.05) % 1 : 0.2);
  const SPX = IX + IW * 0.44, SPY = IY + 34;
  dot(SPX, SPY, 9, STEEL_D); dot(SPX, SPY, 7, COPPER); dot(SPX, SPY, 2.4, STEEL);
  const sa = on ? t * 3 : 0;
  for (let k = 0; k < 3; k++) ln(SPX, SPY, SPX + Math.cos(sa + k * 2.094) * 7, SPY + Math.sin(sa + k * 2.094) * 7, STEEL_D, 0.7);
  ln(SPX, SPY + 7, hx, hy, on ? '#e8a060' : '#4a3020', 0.6);
  RR(hx - 3, hy - 3, 6, 6, 1.2, L('#e8c040', '#c8a030', '#2a2618'));
