    ctx.fillStyle = g; ctx.beginPath(); ctx.roundRect(X(ax), Y(ay), aw * S, ah * S, 12 * S); ctx.fill();
    for (let r = ax + 12; r < ax + aw - 10; r += 10) R(r, ay, 1.2, ah, 'rgba(0,0,0,0.18)');
