  ctx.beginPath(); ctx.arc(X(HX + HW / 2 - 52), Y(HY - 23), 4 * S, 0, Math.PI); ctx.stroke();
  R(HX + HW / 2 - 56.8, HY - 27, 1.6, 4, on ? '#ff4040' : '#3a1a1a'); R(HX + HW / 2 - 48.8, HY - 27, 1.6, 4, on ? '#40c0ff' : '#1a3040');
  text('CRYON SUPERCONDUCTOR', HX + HW / 2 + 6, HY - 22, 7, on ? (night ? '#9ae0ff' : '#e8f4ff') : '#3a4250');
  if (on && night) _lgAdd(K, HX + HW / 2, HY - 22, 70, '90,200,255', 0.2);

