      R(fx, fy, 70, 4, '#2a2c30'); RR(fx + 70, fy - 10, 16, 14, 2, '#e8c040'); R(fx + 78, fy - 8, 7, 5, '#a8d0e8');
      for (const wx of [fx + 8, fx + 20, fx + 56, fx + 78]) dot(wx, fy + 6, 2.6, '#101010');
