    RR(fx, GND + 3, 10, 7.4, 1.4, '#f0b020'); R(fx + 1.4, GND - 2, 6, 5, 'rgba(40,44,50,0.5)'); ln(fx + 1.4, GND - 2, fx + 7.4, GND - 2, '#2a2c30', 0.8);
    dot(fx + 2.4, GND + 11, 1.8, '#1a1a1c'); dot(fx + 8, GND + 11, 1.8, '#1a1a1c'); dot(fx + 5, GND + 0.6, 1.3, _N_SKIN[3]);
    const mx = dir > 0 ? fx + 10 : fx; ln(mx, GND + 10.4, mx, GND - 3, '#3a3c40', 0.9); ln(mx, GND + 8.6, mx + dir * 7, GND + 8.6, '#3a3c40', 0.9);
