    if (detail) for (let m = 1; m < 6; m++) R(x0 + 16 + m * (w - 32) / 6 - 0.3, c1 + 4.5, 0.6, 6.5, 'rgba(0,0,0,0.35)');

    // glazing: five bays a floor
    const floors = Math.round((GND - 35 - top) / 15), FH = (GND - 35 - top) / floors;
    const bay = (w - 12) / 5;
