      for (let s = 0; s < 3; s++) { const i = (t * 0.25 + s / 3 + m * 0.17) % 1 * (CURVE.length - 1), a = CURVE[Math.floor(i)]; _lgAdd(K, mx(a[0]), a[1], 9, '255,240,210', 0.55); }
