  for (let i = 1; i < 8; i++) { const x = xl + PW * i / 8; ln(x, archY(x), x, PY + 11, L('rgba(232,236,239,0.9)', 'rgba(110,120,140,0.8)', 'rgba(60,60,64,0.8)'), 0.7); }
