    for (const k of [0.3, 0.58, 0.82]) { const hw = AW * Math.sqrt(1 - k * k); ln(AX - hw, AB - AH * k, AX + hw, AB - AH * k, L('rgba(255,255,255,0.8)', 'rgba(122,134,164,0.7)', 'rgba(58,58,62,0.8)'), 0.6); }
    if (on && night) _lgAdd(K, AX, AB - 16, 60, '255,214,150', 0.3);
