    if (detail) for (let u = 0.08; u < 1; u += 0.1) { const x = j0[0] + (j1[0] - j0[0]) * u, y = j0[1] + (j1[1] - j0[1]) * u; ln(x - 0.6, y - 2, x + 0.6, y + 2, 'rgba(0,0,0,0.22)', 0.4); }
