  if (on) dot(377, 108, 1.2, Math.sin(t * 4) > 0 ? '#ff3020' : '#5a1810');

  // Payload processing facility (small hangar with a hatch door and gantry crane)
  R(346, 190, 66, 52, 'rgba(0,0,0,0.22)');
  R(340, 186, 66, 14, L('#a8a8a0', '#3a3a3e', '#1e1e20'));
  R(340, 200, 66, 40, L('#dedcd4', '#54545a', '#26262a'));
  if (detail) { for (let x = 344; x < 404; x += 8) R(x, 188, 0.7, 12, 'rgba(0,0,0,0.14)'); for (let y = 204; y < 238; y += 6) R(340, y, 66, 0.5, 'rgba(0,0,0,0.08)'); }
  R(362, 210, 22, 30, L('#8a8a84', '#30303a', '#181818'));
  if (detail) for (let y = 210; y < 240; y += 5) R(362, y, 22, 0.6, 'rgba(0,0,0,0.25)');
  R(346, 206, 12, 6, on ? (night ? '#8ad0ff' : '#3a5a70') : '#121416'); R(388, 206, 12, 6, on ? (night ? '#8ad0ff' : '#3a5a70') : '#121416');
  text('PPF-1', 373, 194, 6, L('#2a3a5a', '#a0b8d8', '#2a2a2a'));
  R(336, 182, 6, 4, STEEL); R(402, 190, 8, 4, STEEL);
  lamp(373, 207, 1.3, '255,230,150');

