  if (detail) { R(454, 372, 34, 3, L('#8a8a86', '#34343a', '#181818')); for (let y = 380; y < 420; y += 8) { R(458, y, 26, 0.8, 'rgba(255,255,255,0.06)'); R(456, y, 2, 4, L('#8a8a86', '#34343a', '#181818')); R(484, y, 2, 4, L('#8a8a86', '#34343a', '#181818')); } }
