      if (detail) { for (let y = baseY - 145; y < baseY - 10; y += 22) R(bx - 6, y, 12, 0.5, seam); if (iced) R(bx - 6, baseY - 84, 12, 84, 'rgba(200,232,255,0.30)'); }
