    cyl(cx - 8, baseY - 290, 16, 40);
    ctx.fillStyle = body; ctx.beginPath(); ctx.moveTo(X(cx - 8), Y(baseY - 290)); ctx.quadraticCurveTo(X(cx - 7.5), Y(baseY - 308), X(cx), Y(baseY - 320)); ctx.quadraticCurveTo(X(cx + 7.5), Y(baseY - 308), X(cx + 8), Y(baseY - 290)); ctx.closePath(); ctx.fill();
    if (on) {
      ctx.save(); ctx.beginPath(); ctx.moveTo(X(cx - 8), Y(baseY - 290)); ctx.quadraticCurveTo(X(cx - 7.5), Y(baseY - 308), X(cx), Y(baseY - 320)); ctx.quadraticCurveTo(X(cx + 7.5), Y(baseY - 308), X(cx + 8), Y(baseY - 290)); ctx.closePath(); ctx.clip();
      R(cx - 6, baseY - 322, 2.4, 34, night ? 'rgba(255,255,255,0.10)' : 'rgba(255,255,255,0.5)'); R(cx + 2, baseY - 322, 8, 34, 'rgba(0,0,0,0.14)'); ctx.restore();
    }
    R(cx - 8, baseY - 291, 16, 1.6, band);                                      // fairing/upper-stage join
    R(cx - 8, baseY - 274, 16, 0.8, seam);
    R(cx - 0.4, baseY - 290, 0.8, 22, seam);                                    // fairing split line
    R(cx - 0.3, baseY - 326, 0.6, 8, STEEL);                                    // tip probe
    // mission roundel + colour band + name
    dot(cx, baseY - 226 + 34, 3.2, L('#c05030', '#5a2818', '#2a120c')); dot(cx, baseY - 226 + 34, 2, L('#f4f4f0', '#8a8a86', '#3a3a38')); dot(cx, baseY - 226 + 34, 1, L('#2a4a8a', '#1a2c50', '#141a26'));
    R(cx - 10, baseY - 262, 20, 2, L('#2a4a8a', '#1a2c50', '#141a26'));
