        for (let m = 0; m < 3; m++) ell(fx, top + fl * (0.16 + m * 0.14), fw * (0.42 - m * 0.08), 2 * (1 - m * 0.2), `rgba(255,255,255,${(0.6 - m * 0.15).toFixed(2)})`);
