    R(478, 30, 56, 4, L('#8a3a22', '#4a2014', '#1e0e08')); ln(478, 32, 506, 44, RUST, 1.2); R(476, 32, 4, 12, STEEL); ln(478, 44, 478, 58, 'rgba(40,40,40,0.7)', 0.7); R(476, 58, 4, 3, L('#e8b820', '#7a6410', '#2a2208'));   // jib crane + hook
