      ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(X(bx - 4), Y(by)); ctx.lineTo(X(bx + 4), Y(by)); ctx.lineTo(X(bx), Y(by + fl)); ctx.closePath(); ctx.fill();
      ctx.restore();
