    ctx.fillStyle = 'rgba(0,0,0,0.12)'; for (let k = 0; k < 3; k++) ctx.fillRect(aX0 - 2*S + k*1*S, hY1 + k*2.4*S + 1.6*S, aX1 - aX0 + 4*S - k*2*S, 0.4*S);
