  // yard apron with bay lines
  ctx.fillStyle = on ? '#33363a' : '#202224'; ctx.fillRect(dX1, dkY0 - 6*S, yX1 - dX1, Y(0.86) - dkY0 + 6*S);
  const nDock = 4, dStep = (dkY1 - dkY0 - 4*S)/nDock;
