    ctx.fillStyle = on ? '#2a2e34' : '#16181a'; ctx.beginPath(); ctx.roundRect(pxl, pyl, 6*S, 18*S, 1*S); ctx.fill();
    ctx.fillStyle = on ? amber : '#5a4020'; ctx.fillRect(pxl, pyl + 1.5*S, 6*S, 1*S); ctx.fillRect(pxl, pyl + 15.5*S, 6*S, 1*S);
    ctx.fillStyle = on ? (night || expo ? '#ffe0a0' : '#f0f0f0') : '#4a4a4a';
