    if (on) for (let j = 0; j < 3; j++) { const q = (t * 0.5 + j / 3 + sx) % 1; ell(sx + 3.5 + Math.sin(t * 3 + j) * 1.2, WT - 24 - q * 16, 2.8 + q * 2.4, 1.5, `rgba(255,255,255,${(0.16 * (1 - q)).toFixed(2)})`); }
