    ctx.fillStyle = g; ctx.beginPath(); ctx.roundRect(X(cx - 10), Y(top), 20 * S, (GND - top - 4) * S, [10 * S, 10 * S, 2 * S, 2 * S]); ctx.fill();
    for (const lx of [-8, 8]) R(cx + lx - 1, GND - 6, 2, 6, L('#6a7078', '#2a2e34', '#18191c'));
    for (const by of [top + 14, GND - 14]) R(cx - 10, by, 20, 1.2, L('rgba(90,100,110,0.4)', 'rgba(0,0,0,0.35)', 'rgba(0,0,0,0.35)'));
