      if (fine && k % 5 === 2) { const [lx, ly] = ringPt(a, -12); dot(lx, ly, 0.9, on ? (Math.sin(t * 2 + k) > -0.7 ? '#60ff90' : '#1a5a2a') : '#1a2a1a'); }
