    g.addColorStop(0, L('#ffffff', '#6a7280', '#2e3236')); g.addColorStop(1, L('#b8c0c8', '#30363e', '#1a1c20'));
    ctx.fillStyle = g; ctx.beginPath(); ctx.roundRect(X(12), Y(hy), 96 * S, 12 * S, 6 * S); ctx.fill();
    if (detail) for (let b = 30; b < 100; b += 22) R(b, hy, 1, 12, 'rgba(0,0,0,0.12)');
