  for (let k = -2; k <= 2; k++) { const hh = 26 * Math.sqrt(1 - (k / 3) ** 2); ln(68 - hh, 472 + k * 8.6, 68 + hh, 472 + k * 8.6, L('#5a3818', '#2a1a10', '#160e08'), 0.6); }
