    R(tx, ty, 16, 16, L('#5a6068', '#2a2e34', '#1a1c1e')); R(tx + 2, ty + 2, 12, 3, L('#7a8088', '#3a3e44', '#222428'));
    dot(tx + 8, ty + 10, 2, on ? '#ffd040' : '#3a3420');
