  for (const [x, y] of [[720, 560], [690, 548]]) { R(x - 5, y - 1, 10, 2, L('#6a6e74', '#3a3e44', '#222428')); }
  for (const o of [-3, 0, 3]) ln(720, 556 + o, SBX + 70, SBY + 46 + o * 0.3, 'rgba(30,30,30,0.5)', 0.4);
