  if (on) for (let j = 0; j < 5; j++) { const q = (t * 0.25 + j / 5) % 1; dot(484 + j * 18 + Math.sin(t + j) * 2, 228 - q * 16, 2 + q * 5, `rgba(235,245,255,${(0.3 * (1 - q)).toFixed(2)})`); }
