  const coil = (cy, front) => {
    ctx.strokeStyle = L(front ? '#d89a50' : '#8a5a2a', front ? '#b07a40' : '#5a3a20', front ? '#3a2a1a' : '#241a10'); ctx.lineWidth = 7 * S;
    ctx.beginPath(); ctx.ellipse(X(VX), Y(cy), 46 * S, 9 * S, 0, front ? 0 : Math.PI, front ? Math.PI : Math.PI * 2); ctx.stroke();
    if (front) { ctx.strokeStyle = 'rgba(255,255,255,0.28)'; ctx.lineWidth = 1.2 * S; ctx.beginPath(); ctx.ellipse(X(VX), Y(cy - 2.5), 46 * S, 9 * S, 0, 0.2, Math.PI - 0.2); ctx.stroke(); }
  };
