    og.addColorStop(0, '#ffffff'); og.addColorStop(0.3, '#f4d0ff'); og.addColorStop(0.7, 'rgba(190,80,255,0.95)'); og.addColorStop(1, 'rgba(120,30,220,0)');
    ctx.fillStyle = og; ctx.beginPath(); ctx.arc(X(VX), Y(OY + Math.sin(t * 1.1) * 2), orbR * 1.2 * S, 0, Math.PI * 2); ctx.fill();
