      for (let s = 1; s <= 6; s++) { const u = s / 6; ctx.lineTo(X(VX + (tx - VX) * u + (_cmFrac(seed + s) - 0.5) * 10 * (1 - u)), Y(OY + (ty - OY) * u + (_cmFrac(seed * 2 + s) - 0.5) * 8 * (1 - u))); }
