    ctx.fillStyle = bg; ctx.beginPath(); ctx.moveTo(X(VX - 20), Y(VT)); ctx.lineTo(X(VX + 20), Y(VT)); ctx.lineTo(X(VX + 44), Y(0)); ctx.lineTo(X(VX - 44), Y(0)); ctx.closePath(); ctx.fill();
